67	    private void saveSettings() {
68	        Constants.EncryptionType encryptionType = encryptionFragment.getEncryptionType();
69	        Constants.AuthMethod authMethod = authenticationFragment.getAuthMethod();
70	
71	        settings.setEncryption(encryptionType);
72	        settings.setAuthMethod(authMethod);
73	
74	        if (authMethod == Constants.AuthMethod.PASSWORD || authMethod == Constants.AuthMethod.PIN) {
75	            String password = authenticationFragment.getPassword();
76	            settings.setAuthCredentials(password);
77	        }
78	
79	        settings.setFirstTimeWarningShown(true);
80	    }
