/** With password based encryption an authentication is mandatory, with the Android
 *  KeyStore it is optional and therefore disabled by default. */
private Constants.AuthMethod getDefaultAuthMethod() {
    if (encryptionType == Constants.EncryptionType.PASSWORD)
        return Constants.AuthMethod.PASSWORD;
    else
        return Constants.AuthMethod.NONE;
}

/** Checks if an authentication method is still a sensible choice for the currently
 *  selected encryption type. */
private boolean canKeepAuthMethod(Constants.AuthMethod method) {
    if (encryptionType == Constants.EncryptionType.PASSWORD) {
        // Password based encryption needs either a password or a PIN
        return method == Constants.AuthMethod.PASSWORD || method == Constants.AuthMethod.PIN;
    } else {
        // Everything is allowed with the KeyStore, but a password or PIN the user has
        // not started to fill in yet is only the leftover mandatory default and would
        // block the navigation, even though the slide says it is optional.
        if (method == Constants.AuthMethod.PASSWORD || method == Constants.AuthMethod.PIN)
            return passwordInput != null && passwordInput.getText() != null &&
                    passwordInput.getText().length() > 0;

        return true;
    }
}

private void setAuthMethod(Constants.AuthMethod method) {
    authMethod = method;

    if (selection != null && selectionMapping != null)
        selection.setSelection(selectionMapping.indexOfValue(method));
}

public Constants.AuthMethod getAuthMethod() {
    if (authMethod != null)
        return authMethod;

    return getDefaultAuthMethod();
}

