444	                String password = passwordInput.getText().toString();
445	                String confirm = passwordConfirm.getText().toString();
446	
447	                if (! password.isEmpty()) {
448	                    if (password.length() < minLength) {
449	                        displayWarning(lengthWarning);
450	                        return false;
451	                    } else {
452	                        if (! confirm.isEmpty() && confirm.equals(password)) {
453	                            hideWarning();
454	                            return true;
455	                        } else {
456	                            displayWarning(confirmPasswordWarning);
457	                            return false;
458	                        }
459	                    }
460	                } else {
461	                    displayWarning(noPasswordWarning);
462	                    return false;
463	                }
464	            } else if (authMethod == Constants.AuthMethod.DEVICE) {
465	                KeyguardManager km = (KeyguardManager) getContext().getSystemService(KEYGUARD_SERVICE);
466	
467	                if (android.os.Build.VERSION.SDK_INT < android.os.Build.VERSION_CODES.LOLLIPOP) {
468	                    displayWarning(R.string.settings_toast_auth_device_pre_lollipop);
469	                    return false;
470	                } else if (! km.isKeyguardSecure()) {
471	                    displayWarning(R.string.settings_toast_auth_device_not_secure);
472	                    return false;
473	                }
474	
475	                hideWarning();
476	
477	                return true;
478	            } else {
479	                hideWarning();
480	
481	                return true;
482	            }
483	        }
